class TransformCallback implements StreamCallback {
    def fromTime
    def toTime
    def hasData = true  // <--- added flag

    TransformCallback(fromTime, toTime) {
        this.fromTime = fromTime
        this.toTime = toTime
    }

    @Override
    void process(InputStream inputStream, OutputStream outputStream) throws IOException {

        def parser = new JsonSlurper()
        def parsed = parser.parse(inputStream)
        // If response is empty array or null -> skip writing and mark flag
        if (!parsed || (parsed instanceof List && parsed.isEmpty())) {
            hasData = false
            return
        }

        // Ensure parsed is always a list
        def records = (parsed instanceof List) ? parsed : [parsed]
		def transformed = []

        // Current timestamp (for inserted_at, updated_at)

        // def now = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))
		// def now = ZonedDateTime.now(ZoneId.of("Asia/Kolkata")).format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))

        records.collect { rec ->
            def entryExit = (rec.entry_exit instanceof List && rec.entry_exit) ? rec.entry_exit[0] : [:]
            def direction = entryExit.direction ?: "unknown"
            def timestamp = entryExit.timestamp
            def newRec = [:]

            // Flatten entry_exit data
            newRec["_id"] = rec._id
            newRec["cameraId"] = entryExit.cameraId
            newRec["objectType"] = entryExit.objectType
            newRec["licensePlateNo"] = entryExit.licensePlateNo
            newRec["locationId"] = entryExit.locationId
            newRec["locationType"] = entryExit.locationType
            newRec["direction"] = direction
            newRec["lpCountry"] = entryExit.lpCountry

            // Add cab/provider details
            def provider = rec.provider
            newRec["cab_type"] = provider
            newRec["service_provider"] = provider

            // Add timestamp field based on direction
            if (direction == "entry" && timestamp) {
                newRec["entry_time"] = timestamp
            } else if (direction == "exit" && timestamp) {
                newRec["exit_time"] = timestamp
            }

            // Add audit timestamps
            // newRec["inserted_at"] = now
            // newRec["updated_at"] = now

            // Add start_time and end_time from FlowFile attributes

            newRec["start_time"] = fromTime
            newRec["end_time"] = toTime

            // Add available field
            // newRec["available"] = null

            // Remove nulls
            // return newRec.findAll { k, v -> v != null }

			transformed << newRec
        }

        // If no valid records
        if (transformed.isEmpty()) {
            hasData = false
            return
        }

        // Output as pretty JSON
        def jsonOut = JsonOutput.prettyPrint(JsonOutput.toJson(transformed))
        outputStream.write(jsonOut.getBytes(StandardCharsets.UTF_8))
    }
}

