import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.commons.io.IOUtils
import java.nio.charset.StandardCharsets

def flowFile = session.get()
if (!flowFile) return

def content = new StringBuilder()

session.read(flowFile, { inputStream ->
    content.append(IOUtils.toString(inputStream, StandardCharsets.UTF_8))
} as InputStreamCallback)

def body = content.toString().trim()

// Conditions for "no data"
boolean isEmptyResponse =
        body == "" ||
        body == "null" ||
        body == "[]" ||
		body == "[ ]" ||
        body == "{}"

// If InvokeHTTP returned empty / null → allow it to go to PutSQL
if (isEmptyResponse) {
    flowFile = session.putAttribute(flowFile, "flow.b2bapp_err_desc", "InvokeHTTP returned empty response")
    session.transfer(flowFile, REL_SUCCESS)
}
// If real data exists → drop it (do not log failure)
else {
    session.remove(flowFile)
}

